-- No rules are activated or seeded.
CREATE TABLE IF NOT EXISTS hs_data_condition_policies(tenant_id uuid NOT NULL,collection text NOT NULL,version integer NOT NULL,rules jsonb NOT NULL,PRIMARY KEY(tenant_id,collection),FOREIGN KEY(tenant_id,collection) REFERENCES hs_data_collections(tenant_id,id));
CREATE TABLE IF NOT EXISTS hs_data_condition_versions(tenant_id uuid NOT NULL,collection text NOT NULL,version integer NOT NULL,rules jsonb NOT NULL,schema_version integer NOT NULL,actor_id text NOT NULL REFERENCES hs_users(id),operation_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(tenant_id,collection,version),FOREIGN KEY(tenant_id,collection) REFERENCES hs_data_collections(tenant_id,id));
CREATE TABLE IF NOT EXISTS hs_data_condition_previews(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,workspace_id text NOT NULL REFERENCES hs_workspaces(id),actor_id text NOT NULL REFERENCES hs_users(id),collection text NOT NULL,expected_version integer NOT NULL,schema_version integer NOT NULL,policy_version integer NOT NULL,data_revision bigint NOT NULL,authority_revision text NOT NULL,rules_hash text NOT NULL,draft_revision text,review_hash text NOT NULL,blocked boolean NOT NULL,expires_at timestamptz NOT NULL DEFAULT clock_timestamp()+interval '10 minutes');
CREATE TABLE IF NOT EXISTS hs_data_condition_operations(tenant_id uuid NOT NULL,actor_id text NOT NULL REFERENCES hs_users(id),operation_id uuid NOT NULL,request_hash text NOT NULL,collection text NOT NULL,applied_version integer NOT NULL,PRIMARY KEY(tenant_id,actor_id,operation_id));
ALTER TABLE hs_data_schema_dependencies ADD COLUMN IF NOT EXISTS condition_collection text;
DROP TRIGGER IF EXISTS hs_data_condition_versions_immutable ON hs_data_condition_versions;
CREATE TRIGGER hs_data_condition_versions_immutable BEFORE UPDATE OR DELETE ON hs_data_condition_versions FOR EACH ROW EXECUTE FUNCTION hs_data_history_immutable();
